SELECT id, order_id, carrier, delivered_date, status, SUM(cost) OVER (PARTITION BY carrier ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cost, AVG(cost) OVER (PARTITION BY order_id) AS order_id_avg_cost, SUM(cost) OVER (PARTITION BY carrier ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cost, AVG(cost) OVER (PARTITION BY YEAR(shipped_date), status ORDER BY cost, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS cost_avg_6_prior, STDDEV_SAMP(cost) OVER (PARTITION BY DATE_TRUNC('YEAR', shipped_date), order_id) AS shipped_date_period_stddev_samp_cost FROM shipments WHERE delivered_date <= '2023-08-22'
